1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
wifi: mac80211: remove station if connection prep fails

If connection preparation fails for MLO connections, then the
interface is completely reset to non-MLD. In this case, we must
not keep the station since it's related to the link of the vif
being removed. Delete an existing station. Any "new_sta" is
already being removed, so that doesn't need changes.

This fixes a use-after-free/double-free in debugfs if that's
enabled, because a vif going from MLD (and to MLD, but that's
not relevant here) recreates its entire debugfs.

Cc: stable@vger.kernel.org
Fixes: 81151ce462e5 ("wifi: mac80211: support MLO authentication/association with one link")
Reviewed-by: Miriam Rachel Korenblit <miriam.rachel.korenblit@intel.com>
Link: https://patch.msgid.link/20260505151533.c4e52deb06ad.Iafe56cec7de8512626169496b134bce3a6c17010@changeid
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The bug occurs because in `ieee80211_prep_connection`, when MLO connection preparation fails, the function calls `ieee80211_vif_set_links(sdata, 0, 0)` to reset the vif to non-MLD and recreate its debugfs. However, if an existing station (`have_sta`) associated with the vif's link was present, it was not destroyed before the reset. This leaves a stale station that holds references to debugfs entries that are being freed and recreated, leading to use-after-free or double-free in debugfs.

Here is the patch:

 static int ieee80211_prep_connection(struct ieee80211_sub_if_data *sdata,
 				     struct cfg80211_bss *cbss, s8 link_id,
 				     const u8 *ap_mld_addr, bool assoc,
 				     struct ieee80211_conn_settings *conn,
 				     bool override,
 				     unsigned long *userspace_selectors)
 {
 	struct ieee80211_local *local = sdata->local;
 	struct ieee80211_if_managed *ifmgd = &sdata->u.mgd;
 	struct ieee80211_bss *bss = (void *)cbss->priv;
 	struct sta_info *new_sta = NULL;
 	struct ieee80211_link_data *link;
-	bool have_sta = false;
+	struct sta_info *have_sta = NULL;
 	bool mlo;
 	int err;
 	u16 new_links;

 	if (link_id >= 0) {
 		mlo = true;
 		if (WARN_ON(!ap_mld_addr))
 			return -EINVAL;
 		new_links = BIT(link_id);
 	} else {
 		if (WARN_ON(ap_mld_addr))
 			return -EINVAL;
 		ap_mld_addr = cbss->bssid;
 		new_links = 0;
 		link_id = 0;
 		mlo = false;
 	}

-	if (assoc) {
-		rcu_read_lock();
+	if (assoc)
 		have_sta = sta_info_get(sdata, ap_mld_addr);
-		rcu_read_unlock();
-	}

 	if (mlo && !have_sta &&
 	    WARN_ON(sdata->vif.valid_links || sdata->vif.active_links))
 		return -EINVAL;

 	err = ieee80211_vif_set_links(sdata, new_links, 0);
 	if (err)
 		return err;

 	link = sdata_dereference(sdata->link[link_id], sdata);
 	if (WARN_ON(!link)) {
 		err = -ENOLINK;
 		goto out_err;
 	}

 	if (WARN_ON(!ifmgd->auth_data && !ifmgd->assoc_data)) {
 		err = -EINVAL;
 		goto out_err;
 	}

 	/* If a reconfig is happening, bail out */
 	if (local->in_reconfig) {
 		err = -EBUSY;
 		goto out_err;
 	}

 	if (!have_sta) {
 		if (mlo)
 			new_sta = sta_info_alloc_with_link(sdata, ap_mld_addr,
 							   link_id, cbss->bssid,
 							   GFP_KERNEL);
 		else
 			new_sta = sta_info_alloc(sdata, ap_mld_addr, GFP_KERNEL);

 		if (!new_sta) {
 			err = -ENOMEM;
 			goto out_err;
 		}

 		if (ifmgd->auth_data &&
 		    (ifmgd->auth_data->algorithm == WLAN_AUTH_EPPKE ||
 		     ifmgd->auth_data->algorithm == WLAN_AUTH_IEEE8021X))
 			new_sta->sta.epp_peer = true;

 		new_sta->sta.mlo = mlo;
 	}

 	/*
 	 * Set up the information for the new channel before setting the
 	 * new channel. We can't - completely race-free - change the basic
 	 * rates bitmap and the channel (sband) that it refers to, but if
 	 * we set it up before we at least avoid calling into the driver's
 	 * bss_info_changed() method with invalid information (since we do
 	 * call that from changing the channel - only for IDLE and perhaps
 	 * some others, but ...).
 	 *
 	 * So to avoid that, just set up all the new information before the
 	 * channel, but tell the driver to apply it only afterwards, since
 	 * it might need the new channel for that.
 	 */
 	if (new_sta) {
 		const struct cfg80211_bss_ies *ies;
 		struct link_sta_info *link_sta;

 		rcu_read_lock();
 		link_sta = rcu_dereference(new_sta->link[link_id]);
 		if (WARN_ON(!link_sta)) {
 			rcu_read_unlock();
 			sta_info_free(local, new_sta);
 			err = -EINVAL;
 			goto out_err;
 		}

 		err = ieee80211_mgd_setup_link_sta(link, new_sta,
 						   link_sta, cbss);
 		if (err) {
 			rcu_read_unlock();
 			sta_info_free(local, new_sta);
 			goto out_err;
 		}

 		memcpy(link->u.mgd.bssid, cbss->bssid, ETH_ALEN);

 		/* set timing information */
 		link->conf->beacon_int = cbss->beacon_interval;
 		ies = rcu_dereference(cbss->beacon_ies);
 		if (ies) {
 			link->conf->sync_tsf = ies->tsf;
 			link->conf->sync_device_ts =
 				bss->device_ts_beacon;

 			ieee80211_get_dtim(ies,
 					   &link->conf->sync_dtim_count,
 					   NULL);
 		} else if (!ieee80211_hw_check(&sdata->local->hw,
 					       TIMING_BEACON_ONLY)) {
 			ies = rcu_dereference(cbss->proberesp_ies);
 			/* must be non-NULL since beacon IEs were NULL */
 			link->conf->sync_tsf = ies->tsf;
 			link->conf->sync_device_ts =
 				bss->device_ts_presp;
 			link->conf->sync_dtim_count = 0;
 		} else {
 			link->conf->sync_tsf = 0;
 			link->conf->sync_device_ts = 0;
 			link->conf->sync_dtim_count = 0;
 		}
 		rcu_read_unlock();
 	}

 	if (new_sta || override) {
 		/*
 		 * Only set this if we're also going to calculate the AP
 		 * settings etc., otherwise this was set before in a
 		 * previous call. Note override is set to %true in assoc
 		 * if the settings were changed.
 		 */
 		link->u.mgd.conn = *conn;
 		err = ieee80211_prep_channel(sdata, link, link->link_id, cbss,
 					     mlo, &link->u.mgd.conn,
 					     userspace_selectors);
 		if (err) {
 			if (new_sta)
 				sta_info_free(local, new_sta);
 			goto out_err;
 		}
 		/* pass out for use in assoc */
 		*conn = link->u.mgd.conn;
 	}

 	if (new_sta) {
 		/*
 		 * tell driver about BSSID, basic rates and timing
 		 * this was set up above, before setting the channel
 		 */
 		ieee80211_link_info_change_notify(sdata, link,
 						  BSS_CHANGED_BSSID |
 						  BSS_CHANGED_BASIC_RATES |
 						  BSS_CHANGED_BEACON_INT);

 		if (assoc)
 			sta_info_pre_move_state(new_sta, IEEE80211_STA_AUTH);

 		err = sta_info_insert(new_sta);
 		new_sta = NULL;
 		if (err) {
 			sdata_info(sdata,
 				   "failed to insert STA entry for the AP (error %d)\n",
 				   err);
 			goto out_release_chan;
 		}
 	} else
 		WARN_ON_ONCE(!ether_addr_equal(link->u.mgd.bssid, cbss->bssid));

 	/* Cancel scan to ensure that nothing interferes with connection */
 	if (local->scanning)
 		ieee80211_scan_cancel(local);

 	return 0;

 out_release_chan:
 	ieee80211_link_release_channel(link);
 out_err:
+	if (mlo && have_sta)
+		WARN_ON(__sta_info_destroy(have_sta));
 	ieee80211_vif_set_links(sdata, 0, 0);
 	return err;
 }



